
-- Enums

CREATE TABLE global_region_enum (
  code VARCHAR(8) NOT NULL PRIMARY KEY,     -- EMEA / APAC / AMER
  name VARCHAR(64) NOT NULL,
  sort_order SMALLINT NOT NULL,
  is_active BOOLEAN NOT NULL
);

CREATE UNIQUE INDEX ux_global_region_enum_name ON global_region_enum(name);


CREATE TABLE country_enum (
  code2 CHAR(2) NOT NULL PRIMARY KEY,
  code3 CHAR(3) NOT NULL,
  numeric_code CHAR(3) NOT NULL,
  name VARCHAR(128) NOT NULL,
  official_name VARCHAR(256) NULL,
  common_name VARCHAR(256) NULL,
  global_region VARCHAR(8) NOT NULL,
  is_active BOOLEAN NOT NULL,
  CONSTRAINT fk_country_enum_global_region
    FOREIGN KEY (global_region) REFERENCES global_region_enum(code)
);
CREATE UNIQUE INDEX ux_country_enum_code3 ON country_enum(code3);
CREATE UNIQUE INDEX ux_country_enum_numeric_code ON country_enum(numeric_code);
CREATE INDEX ix_country_enum_global_region ON country_enum(global_region);


CREATE TABLE ccy_enum (
  code CHAR(3) PRIMARY KEY,
  numeric_code CHAR(3) NULL,
  name VARCHAR(128) NOT NULL,
  minor_units SMALLINT NULL,
  is_active BOOLEAN NOT NULL,
  withdrawal_date VARCHAR(32) NULL
);


-- Demo tables: client, product, purchase
-- (HSQLDB supports INFORMATION_SCHEMA for introspection.)

DROP TABLE IF EXISTS purchase;
DROP TABLE IF EXISTS product;
DROP TABLE IF EXISTS client;

CREATE TABLE client (
  id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email    VARCHAR(255) NOT NULL UNIQUE,
  name     VARCHAR(200) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE product (
  id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sku       VARCHAR(64) NOT NULL UNIQUE,
  title     VARCHAR(255) NOT NULL,
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0)
);

CREATE TABLE purchase (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_id   BIGINT NOT NULL,
  product_id  BIGINT NOT NULL,
  qty         INTEGER NOT NULL CHECK (qty > 0),
  ordered_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT fk_purchase_client FOREIGN KEY (client_id) REFERENCES client(id),
  CONSTRAINT fk_purchase_product FOREIGN KEY (product_id) REFERENCES product(id)
);
